WITH latest_match AS (SELECT s.*, latest.event_time FROM sessions s LEFT JOIN LATERAL (SELECT c.event_time FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT browser, country, customer_id, COUNT(*) FILTER (WHERE country = 'DE') AS de_rows, COUNT(*) AS event_count, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, SIZE(COLLECT_SET(browser)) AS num_browsers, COUNT_IF(device = 'tablet') AS tablet_events, COUNT(DISTINCT country) AS distinct_countries, GROUPING(browser) AS gid FROM latest_match GROUP BY CUBE (browser, country, customer_id)
